export const TERMS_PER_PAGE = 50

export const categories = [
  "Tümü",
  "Genel Dilbilim",
  "Sesbilim",
  "Biçimbilim",
  "Sözdizimi",
  "Anlambilim",
  "Edimbilim",
  "Söylem Çözümlemesi",
]

export function getTermsByPage(page: number, category: string = "Tümü", search: string = ""): GlossaryTerm[] {
  let filtered = glossaryTerms
  if (category !== "Tümü") {
    filtered = filtered.filter((t) => t.category === category)
  }
  if (search.trim()) {
    const q = search.toLowerCase()
    filtered = filtered.filter(
      (t) =>
        t.term.toLowerCase().includes(q) ||
        t.definition.toLowerCase().includes(q) ||
        (t.englishEquivalent?.toLowerCase().includes(q) ?? false)
    )
  }
  const start = (page - 1) * TERMS_PER_PAGE
  return filtered.slice(start, start + TERMS_PER_PAGE)
}

export function getTotalPages(category: string = "Tümü", search: string = ""): number {
  let filtered = glossaryTerms
  if (category !== "Tümü") {
    filtered = filtered.filter((t) => t.category === category)
  }
  if (search.trim()) {
    const q = search.toLowerCase()
    filtered = filtered.filter(
      (t) =>
        t.term.toLowerCase().includes(q) ||
        t.definition.toLowerCase().includes(q) ||
        (t.englishEquivalent?.toLowerCase().includes(q) ?? false)
    )
  }
  return Math.ceil(filtered.length / TERMS_PER_PAGE)
}

export function getTotalCount(category: string = "Tümü", search: string = ""): number {
  let filtered = glossaryTerms
  if (category !== "Tümü") {
    filtered = filtered.filter((t) => t.category === category)
  }
  if (search.trim()) {
    const q = search.toLowerCase()
    filtered = filtered.filter(
      (t) =>
        t.term.toLowerCase().includes(q) ||
        t.definition.toLowerCase().includes(q) ||
        (t.englishEquivalent?.toLowerCase().includes(q) ?? false)
    )
  }
  return filtered.length
}
